SYSTEMS = ["llm_only", "tfidf_rag", "graph_rag"]


def run_cases(cases, generate, retrieval_only=False):
    """Run every case through each system in a fixed order.

    Returns a dict with a deterministic ``manifest`` and ``rows``. In
    retrieval-only mode ``generate`` is never called and answers are ``None``.
    Input cases are not mutated.
    """
    case_list = list(cases)
    rows = []
    for case in case_list:
        case_id = case["id"]
        for system in SYSTEMS:
            if retrieval_only:
                answer = None
            else:
                answer = generate(case, system)
            rows.append({"id": case_id, "system": system, "answer": answer})

    manifest = {
        "systems": list(SYSTEMS),
        "case_count": len(case_list),
        "generation_requested": not retrieval_only,
    }
    return {"manifest": manifest, "rows": rows}
